// Pipelining: IF, ID, EX, MEM, WB
// Goal: Overlap stages (Latency 5, Throughput 1/cycle)

// Data Hazard (RAW): Read After Write
R1 = 5;
I1: ADD R1, R2, R3  // Writes R1 (WB Stage)
I2: SUB R4, R1, R5  // Reads R1 (ID/EX Stage)

// Hazard occurs when I2 ID/EX needs R1, but I1's result
// is not yet finalized in the register file.

// Conceptual Pipeline Flow (Without Forwarding):
// I1: IF ID EX MEM WB
// I2:    IF ID S S ID EX... (Stall/Bubble required)

